INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 19, 'theory', 'Quiz: oVirt hosts');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 19, 0, 'When does an oVirt host become a fencing candidate with default settings?', '["After the very first missed answer", "When it has entered maintenance", "When there are at least two failures in a row and at least 60 seconds have passed since the first", "When no machines are left on it"]', 2, 'Both conditions are needed at once: the number of consecutive failures and the time since the first. So a single glitch does not lead to switching a host off.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 19, 1, 'Why does the engine restart HA machines of a failed host only after fencing or a manual confirmation?', '["Otherwise two copies of the machine could open one disk and corrupt the data", "Because other hosts cannot be used earlier", "Because fencing speeds up migration", "Because the portal does not show machines of a failed host"]', 0, 'The engine does not know whether the host is really dead. While it might still be alive, starting a second copy is dangerous; fencing gives certainty that the old copy is stopped.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 19, 2, 'How does NonOperational differ from NonResponsive?', '["They are the same", "NonOperational means the administrator switched the host off", "NonResponsive happens only during upgrades", "With NonOperational the host is reachable but does not meet requirements, such as a missing network or storage"]', 3, 'NonResponsive is a loss of contact with the host. NonOperational is set on a host that answers but is unfit for the cluster''s work.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 19, 3, 'What job does supervdsmd do?', '["Accepts all of the engine''s commands over JSON-RPC", "Performs privileged actions as root: network, mounting, devices", "Stores the engine''s database", "Starts QEMU processes without libvirt"]', 1, 'Commands are accepted by vdsmd under an ordinary user, and anything that needs root rights is requested from supervdsmd.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 19, 4, 'What is the policy to skip fencing when contact is lost with a share of the cluster''s hosts for?', '["To speed up a cluster upgrade", "To save memory on checks", "If many hosts vanish at once, the engine''s own network is probably broken, and healthy hosts must not be fenced", "So that hosts cannot enter maintenance"]', 2, 'A mass loss of contact more often means a problem on the engine''s side or in the shared network. Switching off dozens of live hosts because of it would be a disaster.');
